// GTM plugin — cancel_scheduled_send. Ported verbatim from the host outreach
// tools (workers/api/src/tools/outreach.js); env → api, shared code in the
// pack's parallel lib (same function names, api first).

import { cancelOrDismiss } from './gtm-schedule.mjs';

export const def = {
  name: 'cancel_scheduled_send',
  description: 'Cancel a scheduled send before it fires, or dismiss a terminal failed/partial one (the reply says which of the two happened). A claimed, in-flight send cannot be un-fired — that is the fail-closed guarantee, and it is an operator decision to review rather than a retry queue.',
  input_schema: {
    type: 'object',
    properties: { schedule_id: { type: 'string', description: 'the ss_ schedule id' } },
    required: ['schedule_id'],
  },
};

export async function run(api, input) {
  return cancelOrDismiss(api, input?.schedule_id);
}

// GTM plugin — collect_replies. Read-only: who answered a message we sent.

import { collectReplies } from './gtm-outreach.mjs';

export const def = {
  name: 'collect_replies',
  description: 'Collect every prospect who REPLIED to our outreach: an inbound WhatsApp message landing after our first send to them. Read-only, so it is safe to run on a tick. Each row is {lead_id, name, company, title, phone, linkedin, replied_at, first_contacted_at, sends}. Use to answer "who has answered".',
  input_schema: { type: 'object', properties: {}, required: [] },
};

export async function run(api) {
  return collectReplies(api);
}

// GTM plugin — company_context. The company behind a lead, from the sources
// this install has: a SerpApi search plus a read of the company's own site.

import { companyContextForLead } from './gtm.mjs';

export const def = {
  name: 'company_context',
  description: "Look up the COMPANY behind one lead: search for it, read its own site, and store a short fact sheet (what it does, industry, HQ, website, headcount when the page states one) on the lead. Needs SerpApi connected. Cached for 30 days unless refresh:true. Partial by design — whatever was found is kept and whatever failed is named in errors[]. Feeds the ICP match.",
  input_schema: {
    type: 'object',
    properties: {
      id: { type: 'string' },
      refresh: { type: 'boolean', description: 'ignore the cache and look it up again' },
    },
    required: ['id'],
  },
};

export async function run(api, input) {
  if (!input?.id) return { error: 'id required' };
  return companyContextForLead(api, input.id, { refresh: !!input.refresh });
}

export const def = {
  name: 'connect_gtm_service',
  description: "Connect a prospecting data service by storing its key in this plugin's own table. service is 'serp' (SerpApi, search results), 'pdl' (People Data Labs, person enrichment) or 'twilio' (phone validation; needs both sid and token). Use when the operator pastes a key in chat.",
  input_schema: {
    type: 'object',
    properties: {
      service: { type: 'string', enum: ['serp', 'pdl', 'twilio'] },
      api_key: { type: 'string', description: 'the key, for serp and pdl' },
      sid: { type: 'string', description: 'Twilio account SID' },
      token: { type: 'string', description: 'Twilio auth token' },
    },
    required: ['service'],
  },
};
const NAMES = { serp: 'SerpApi', pdl: 'People Data Labs', twilio: 'Twilio Lookup' };
export async function run(api, input) {
  const service = String(input?.service || '').trim().toLowerCase();
  if (!NAMES[service]) return { ok: false, error: 'service must be serp, pdl or twilio' };
  const put = async (name, value) => {
    await api.db.prepare(
      'INSERT INTO plugin_gtm_connections (name, value, updated_at) VALUES (?, ?, ?) ON CONFLICT(name) DO UPDATE SET value=excluded.value, updated_at=excluded.updated_at',
    ).bind(name, String(value), Date.now()).run();
  };
  if (service === 'twilio') {
    const sid = String(input?.sid || '').trim(); const token = String(input?.token || '').trim();
    if (!sid || !token) return { ok: false, error: 'Twilio needs both the account SID and the auth token' };
    await put('twilio_sid', sid); await put('twilio_token', token);
  } else {
    const k = String(input?.api_key || '').trim();
    if (!k) return { ok: false, error: 'api_key required' };
    await put(`${service}_api_key`, k);
  }
  const st = await api.gateway(service, 'status', {}).catch(() => null);
  await api.log('service_connected', { service });
  return { ok: true, service, connected: !!st?.connected, note: `${NAMES[service]} is connected.` };
}

export const def = {
  name: 'disconnect_gtm_service',
  description: 'Forget the stored key for one prospecting data service (serp, pdl or twilio).',
  input_schema: { type: 'object', properties: { service: { type: 'string', enum: ['serp', 'pdl', 'twilio'] } }, required: ['service'] },
};
export async function run(api, input) {
  const s = String(input?.service || '').trim().toLowerCase();
  if (!['serp', 'pdl', 'twilio'].includes(s)) return { ok: false, error: 'service must be serp, pdl or twilio' };
  const names = s === 'twilio' ? ['twilio_sid', 'twilio_token'] : [`${s}_api_key`];
  for (const n of names) await api.db.prepare('DELETE FROM plugin_gtm_connections WHERE name = ?').bind(n).run();
  await api.log('service_disconnected', { service: s });
  return { ok: true, service: s };
}

// GTM plugin — draft_angles. Drafts, never saves and never sends.

import { getLead } from './gtm.mjs';
import { draftAnglesForLead } from './gtm-outreach.mjs';

const leadNow = (input) => ({ ...(input.lead || {}), ...(input.lead_patch || {}) });

export const def = {
  name: 'draft_angles',
  description: "Draft ranked outreach angles and WhatsApp message bubbles for a fully identified prospect, from the operator profile, the outreach playbook and whatever company context is on file. A DRAFT only — it never sends and never saves; sending stays an explicit, operator-approved action.",
  input_schema: { type: 'object', properties: { id: { type: 'string' } }, required: [] },
};

export async function run(api, input) {
  const lead = input.lead ? leadNow(input) : (input.id ? await getLead(api, input.id) : null);
  if (!lead) return { angles_payload: null, error: 'no lead' };
  return draftAnglesForLead(api, { lead });
}

// GTM plugin — draft_prospect_reply. In the host this was the
// `draft-prospect-reply` WORKFLOW (read_prospect_thread → read_lead_angles →
// read_drafting_rules → pick_next_bubble → compose_reply) fronted by
// POST /api/outreach/wa/draft. A plugin surface drives tools, not workflows,
// so the chain ships as ONE tool over the same lib the step tools share —
// the behaviour and the flat OutreachDraft result shape are unchanged:
// {draft, source: angle|llm|template|none, lead_id?, reason?, step?,
//  first_touch?, angle?, alternatives?, based_on_messages?, at?}.
// NEVER sends — sending stays a separate operator action.

import { draftReply } from './outreach-wa.mjs';

export const def = {
  name: 'draft_prospect_reply',
  description: 'Produce the suggested next message for one prospect conversation: a verbatim approved angle bubble (first touch or follow-up into silence), the default first-touch template when there is no angle, or one composed reply when the prospect has actually said something. force_llm:true composes even into silence. Run with {chat_id} or {lead_id}. A suggestion only — it NEVER sends; sending is a separate operator action.',
  input_schema: {
    type: 'object',
    properties: {
      chat_id: { type: 'string' },
      lead_id: { type: 'string' },
      force_llm: { type: 'boolean', description: 'compose with the model even when they have not replied' },
    },
    required: [],
  },
};

export async function run(api, input) {
  return draftReply(api, {
    chat_id: input?.chat_id || null,
    lead_id: input?.lead_id || null,
    force_llm: !!input?.force_llm,
  });
}

// GTM plugin — edit_lead. The host had no tool for this: POST /api/gtm/leads/:id
// called lib manualEditLead directly (and mapped its throw to a 400 with the
// reason). Tools answer JSON, so a rejected value comes back as { error } and
// the surface's data layer re-throws it for the confirm popover to display.
// Result mirrors the route body: { lead } decorated with state + confidence.

import { manualEditLead, leadState, evaluateConfidence } from './gtm.mjs';

export const def = {
  name: 'edit_lead',
  description: "Manually edit one lead's fields (name / linkedin / email / company / position; '' clears a field), correct the company's LinkedIn page (company_linkedin — a targeted key, never a whole-socials rewrite), or set/clear company_staff_count. A manual edit stamps 'manual' provenance and resolves conflicts on the fields it touched. Returns the updated lead with its re-evaluated state and identity confidence.",
  input_schema: {
    type: 'object',
    properties: {
      id: { type: 'string' },
      name: { type: 'string' },
      linkedin: { type: 'string' },
      email: { type: 'string' },
      company: { type: 'string' },
      position: { type: 'string' },
      socials: { type: 'array', items: { type: 'object' }, description: 'replace the socials array (removed URLs are tombstoned)' },
      company_linkedin: { type: ['string', 'null'], description: 'the COMPANY page URL; null/"" clears it and forgets what the old one resolved to' },
      company_staff_count: { type: ['number', 'string', 'null'], description: 'LinkedIn headcount override; null/"" clears it back to "not checked"' },
    },
    required: ['id'],
  },
};

export async function run(api, input) {
  const { id, ...patch } = input || {};
  if (!id) return { error: 'id required' };
  try {
    const lead = await manualEditLead(api, id, patch);
    return { lead: { ...lead, state: leadState(lead), confidence: evaluateConfidence(lead) } };
  } catch (e) {
    return { error: String(e?.message || e) };
  }
}

